class Program
{
    static void Main()
    {
        for (int i = 0; i < 3; i++)
        {
            Console.WriteLine(MathBox.AddOne(i));
        }
    }
}

class MathBox
{
    public static int AddOne(int value)
    {
        return value + 1;
    }
}

